-- SQL 2026-10-10-29 — Interview Guide question banks seed (generated by
-- scripts/build-inv-question-seed.py from slp-incident-question-banks-FULL.md).
-- Upsert by code; additive. Re-running refreshes wording from the spec.

on conflict (code) do update set label = excluded.label, kind = excluded.kind, preferred_ca = excluded.preferred_ca, sort = excluded.sort, updated_at = now();

on conflict (code) do update set bank = excluded.bank, audience = excluded.audience, stage = excluded.stage, prompt = excluded.prompt, help = excluded.help, answer_type = excluded.answer_type, options = excluded.options, is_critical = excluded.is_critical, is_dig_deeper = excluded.is_dig_deeper, is_confidential = excluded.is_confidential, trigger = excluded.trigger, sort = excluded.sort, version = public.inv_question_bank.version + case when public.inv_question_bank.prompt is distinct from excluded.prompt then 1 else 0 end, updated_at = now();
