insert into public.inv_question_banks (code, label, kind, preferred_ca, sort) values
  ('core', 'Universal core (every investigation)', 'core', null, 0),
  ('hand_ppe', 'Hand / finger / PPE', 'hazard', 'Eliminate hand-in-hazard (fixture, cutter, guard) → specify cut-rated glove at point of use → only then training if knowledge gap proven.', 10),
  ('chemical', 'Chemical / fluid exposure', 'hazard', 'Closed-system transfer / eliminate mouth contact path → stock pump at point of use → label/lock unlabeled containers → training only if SDS knowledge gap proven.', 20),
  ('vehicle', 'Vehicle / mobile equipment', 'hazard', 'Separate people from vehicles (barriers, one-way, no-go zones) → working cameras/alarms → journey management that can say no → training only for proven skill gaps (backing, winter driving).', 30),
  ('slip_trip_fall', 'Slip, trip, fall (incl. from height)', 'hazard', 'Eliminate the walkway hazard or elevated task → engineering (mats, heat, guardrails, mezzanine) → named housekeeping owner → PPE/footwear last.', 40),
  ('stored_energy', 'Stored energy / LOTO / pressure', 'hazard', 'Engineering that forces verify-zero → clear single-owner isolation → procedure that matches the real valve map → authorize-to-LOTO competency. Not “remember to bleed it.”', 50),
  ('manual_handling', 'Manual handling / strain', 'hazard', 'Eliminate the lift (deliver at height, break bulk) → hoist/dolly at point of use → only then technique training.', 60),
  ('line_of_fire', 'Line of fire / struck-by / caught-between / dropped object', 'hazard', 'Keep people out of the line of fire by design → tethering/DROPS → exclusion enforced by role, not hope.', 70),
  ('lifting_rigging', 'Crane / hoist / rigging / suspended load / wireline mast', 'hazard', 'No lift without matching plan + known weight → remove bypassed safety devices → certified roles only → engineering (dedicated lift points, below-the-hook gear).', 80),
  ('confined_space', 'Confined space', 'hazard', 'Eliminate entry → engineering controls on atmosphere → real rescue capability (not paper) → permit discipline.', 90),
  ('hot_work', 'Hot work / fire / explosion', 'hazard', 'Substitute cold methods → engineered spark control → real fire watch (time-boxed, signed) → permit that can stop work.', 100),
  ('spill_env', 'Spill / environmental', 'hazard', 'Eliminate hose transfers where practical → containment + overfill engineering → kit at point of use → notification drill.', 110),
  ('electrical', 'Electrical', 'hazard', 'Dead & verified always · GFCI on temp power · arc-flash labels + PPE by task · eliminate live work by design.', 120),
  ('excavation_trench', 'Excavation / trenching', 'hazard', 'No dig without locate + protection → competent person with stop authority → engineered shields for recurring work.', 130),
  ('wildlife_bear', 'Wildlife / bear / animal', 'hazard', 'Eliminate attractants → engineered food storage → no solo travel in peak habitat → deterrents as last layer. Not “be aware of bears.”', 140),
  ('weather_cold', 'Weather / cold stress / heat', 'hazard', 'Hard weather stop criteria with real authority → shelter and rotation engineered into the job → PPE layers that still allow the task.', 150),
  ('water_drowning_marine', 'Water / marine / dock', 'hazard', 'Eliminate edge exposure → guardrails/nets → PFD + real MOB capability → tide windows as hard gates.', 160),
  ('aviation_helicopter', 'Aviation / helicopter', 'hazard', 'Only approved operators · pilot no-go absolute · eliminate unnecessary flights · engineered LZ control.', 170),
  ('property_damage_no_injury', 'Property damage (no injury)', 'hazard', 'Treat high-energy property damage like a serious near miss — engineer the contact out.', 180),
  ('near_miss_good_catch', 'Near miss / good catch', 'hazard', 'Same as the injury bank for that energy. Never close with “thanks for reporting” alone.', 190),
  ('psychological_violence_harassment', 'Psychological safety / violence / harassment', 'hazard', 'Protect the person · remove/control the hazard (including people/process) · fix reporting trust. Never “mediated conversation” as the only control for credible threats.', 200),
  ('other', 'Other / not listed', 'hazard', null, 210),
  ('culture', 'Supervision & shop culture', 'culture', null, 900),
  ('rootcause', 'Root cause & close-out', 'rootcause', null, 1000)
insert into public.inv_question_bank (code, bank, audience, stage, prompt, help, answer_type, options, is_critical, is_dig_deeper, is_confidential, trigger, sort) values
  ('U1', 'core', array['IP']::text[], 3, 'Walk me through the task start to finish. What were you doing right before, during, and after?', 'Follow-up: seeds timeline', 'text', '[]'::jsonb, true, false, false, '{}'::jsonb, 10),
  ('U2', 'core', array['IP','SUP']::text[], 3, 'What was different about this job today vs. normal?', null, 'multi', '[{"value": "New crew", "label": "New crew"}, {"value": "New tool/equip", "label": "New tool/equip"}, {"value": "Weather", "label": "Weather"}, {"value": "Rush/schedule", "label": "Rush/schedule"}, {"value": "Late shift/fatigue", "label": "Late shift/fatigue"}, {"value": "First time on task", "label": "First time on task"}, {"value": "Client pressure", "label": "Client pressure"}, {"value": "Different location", "label": "Different location"}, {"value": "Nothing different", "label": "Nothing different"}, {"value": "Other", "label": "Other"}]'::jsonb, true, false, false, '{}'::jsonb, 20),
  ('U3', 'core', array['INV']::text[], 3, 'What was the decision point? At what moment was the choice made that led to this?', null, 'text', '[]'::jsonb, true, false, false, '{}'::jsonb, 30),
  ('U4', 'core', array['IP']::text[], 3, 'Why did that make sense at the time?', null, 'chips', '[{"value": "Faster", "label": "Faster", "probe": "What made that OK here? Has it worked before without consequence?"}, {"value": "Easier", "label": "Easier", "probe": "What made that OK here? Has it worked before without consequence?"}, {"value": "Always done this way", "label": "Always done this way", "probe": "What made that OK here? Has it worked before without consequence?"}, {"value": "Right gear not here", "label": "Right gear not here", "probe": "What made that OK here? Has it worked before without consequence?"}, {"value": "Didn’t see the hazard", "label": "Didn’t see the hazard", "probe": "What made that OK here? Has it worked before without consequence?"}, {"value": "Someone told me to", "label": "Someone told me to", "probe": "What made that OK here? Has it worked before without consequence?"}, {"value": "Thought it was fine", "label": "Thought it was fine", "probe": "What made that OK here? Has it worked before without consequence?"}, {"value": "Other", "label": "Other", "probe": "What made that OK here? Has it worked before without consequence?"}]'::jsonb, true, false, false, '{}'::jsonb, 40),
  ('U5', 'core', array['IP','WIT','SUP']::text[], 3, 'Is this how the job is normally done? By you? By others?', null, 'chips', '[{"value": "Only me", "label": "Only me"}, {"value": "Some people", "label": "Some people"}, {"value": "Most people", "label": "Most people", "probe": "How long has this been normal? Who knows?"}, {"value": "Everyone", "label": "Everyone", "probe": "How long has this been normal? Who knows?"}, {"value": "Don’t know", "label": "Don’t know"}]'::jsonb, true, false, false, '{}'::jsonb, 50),
  ('U6', 'core', array['SUP']::text[], 3, 'Was the right tool, equipment, and PPE available, in good condition, at the work location?', null, 'chips', '[{"value": "Yes", "label": "Yes"}, {"value": "Available but not here", "label": "Available but not here", "probe": "Why wasn’t the gap fixed before the job started?"}, {"value": "Damaged", "label": "Damaged", "probe": "Why wasn’t the gap fixed before the job started?"}, {"value": "Not stocked", "label": "Not stocked", "probe": "Why wasn’t the gap fixed before the job started?"}, {"value": "Not owned", "label": "Not owned", "probe": "Why wasn’t the gap fixed before the job started?"}, {"value": "Wrong type", "label": "Wrong type", "probe": "Why wasn’t the gap fixed before the job started?"}]'::jsonb, true, false, false, '{}'::jsonb, 60),
  ('U7', 'core', array['SUP']::text[], 3, 'Was a JSA/THA done, and did it name this hazard with a control that was actually used?', null, 'chips', '[{"value": "No JSA", "label": "No JSA"}, {"value": "JSA missed it", "label": "JSA missed it"}, {"value": "Named but control not used", "label": "Named but control not used", "probe": "Who reviewed it? Was it done at the job, or in the office?"}, {"value": "Named and controlled", "label": "Named and controlled"}, {"value": "JSA was copy-paste", "label": "JSA was copy-paste"}, {"value": "generic", "label": "generic"}]'::jsonb, true, false, false, '{}'::jsonb, 70),
  ('U8', 'core', array['INV']::text[], 3, 'What physical change (tool, equipment, setup, layout, process) would make this mistake impossible or much harder — rather than reminding people?', null, 'text', '[]'::jsonb, true, false, false, '{}'::jsonb, 80),
  ('U9', 'core', array['SUP']::text[], 3, 'Experience on this exact task? Short-service employee? Hours into shift / days into rotation?', null, 'chips', '[{"value": "<1 mo", "label": "<1 mo"}, {"value": "<6 mo", "label": "<6 mo"}, {"value": "<2 yr", "label": "<2 yr"}, {"value": "2 yr+", "label": "2 yr+"}, {"value": "Short-service employee", "label": "Short-service employee"}]'::jsonb, false, true, false, '{}'::jsonb, 90),
  ('U10', 'core', array['IP','SUP']::text[], 3, 'Was anyone rushing, distracted, or under time pressure? Where did the pressure come from?', null, 'multi', '[{"value": "Self", "label": "Self"}, {"value": "Supervisor", "label": "Supervisor"}, {"value": "Client", "label": "Client"}, {"value": "Schedule/bonus", "label": "Schedule/bonus"}, {"value": "Weather window", "label": "Weather window"}, {"value": "Peer", "label": "Peer"}, {"value": "None", "label": "None"}]'::jsonb, false, true, false, '{}'::jsonb, 100),
  ('U11', 'core', array['IP','WIT']::text[], 3, 'Did anyone notice and say something? Did anyone think about stopping the job? Why or why not?', null, 'multi', '[{"value": "Said something", "label": "Said something"}, {"value": "ignored", "label": "ignored"}, {"value": "Thought about it, didn’t", "label": "Thought about it, didn’t"}, {"value": "Didn’t notice", "label": "Didn’t notice"}, {"value": "Stop Work used", "label": "Stop Work used"}, {"value": "Fear of pushback", "label": "Fear of pushback"}, {"value": "“Not my job”", "label": "“Not my job”"}]'::jsonb, false, true, false, '{}'::jsonb, 110),
  ('U12', 'core', array['INV']::text[], 3, 'Which defenses should have stopped this (procedure, JSA, PPE, guard, interlock, supervision, peer check, permit)? For each, why did it fail or get bypassed?', null, 'text', '[]'::jsonb, false, true, false, '{}'::jsonb, 120),
  ('U13', 'core', array['SUP','INV']::text[], 3, 'Is there a procedure–reality gap? Does the written procedure match how the job is actually done under real time/crew/equipment constraints?', null, 'text', '[]'::jsonb, false, true, false, '{}'::jsonb, 130),
  ('U14', 'core', array['SUP']::text[], 3, 'Competency vs. experience: Was the person trained and assessed on this task, or just “experienced in the trade”? When was last demonstration of competence?', null, 'text', '[]'::jsonb, false, true, false, '{}'::jsonb, 140),
  ('U15', 'core', array['INV']::text[], 3, 'Production pressure / goal conflict: Did schedule, client demand, or resource shortage compete with doing it the safe way? How is that conflict normally resolved?', null, 'text', '[]'::jsonb, false, true, false, '{}'::jsonb, 150),
  ('U16', 'core', array['INV']::text[], 3, 'Normalization of deviance: Has this shortcut been used successfully enough times that it stopped feeling like a risk?', null, 'text', '[]'::jsonb, false, true, false, '{}'::jsonb, 160),
  ('H1', 'hand_ppe', array['IP']::text[], 3, 'What exactly caused the injury?', null, 'multi', '[{"value": "Sharp edge/burr", "label": "Sharp edge/burr"}, {"value": "Wire/cable end", "label": "Wire/cable end"}, {"value": "Pinch/crush", "label": "Pinch/crush"}, {"value": "Tool slip", "label": "Tool slip"}, {"value": "Rotating/spinning part", "label": "Rotating/spinning part"}, {"value": "Hot surface", "label": "Hot surface"}, {"value": "Chemical on skin", "label": "Chemical on skin"}, {"value": "Other", "label": "Other"}]'::jsonb, true, false, false, '{}'::jsonb, 10),
  ('H2', 'hand_ppe', array['IP']::text[], 3, 'Was hand protection worn? What kind?', null, 'chips', '[{"value": "None", "label": "None"}, {"value": "Cotton", "label": "Cotton"}, {"value": "Leather", "label": "Leather"}, {"value": "Cut-rated (A1–A9)", "label": "Cut-rated (A1–A9)"}, {"value": "Impact", "label": "Impact"}, {"value": "Chemical-resistant", "label": "Chemical-resistant"}, {"value": "Wrong glove for hazard", "label": "Wrong glove for hazard"}, {"value": "Other", "label": "Other"}]'::jsonb, true, false, false, '{}'::jsonb, 20),
  ('H3', 'hand_ppe', array['IP']::text[], 3, 'If not worn (or wrong type): why not?', null, 'chips', '[{"value": "Forgot", "label": "Forgot", "probe": "What made that OK here? Have you/others done this task bare-handed before?"}, {"value": "Didn’t think needed", "label": "Didn’t think needed", "probe": "What made that OK here? Have you/others done this task bare-handed before?"}, {"value": "Not available", "label": "Not available", "probe": "What made that OK here? Have you/others done this task bare-handed before?"}, {"value": "Wrong size/type", "label": "Wrong size/type", "probe": "What made that OK here? Have you/others done this task bare-handed before?"}, {"value": "Got in the way", "label": "Got in the way"}, {"value": "Never wear them for this", "label": "Never wear them for this", "probe": "What made that OK here? Have you/others done this task bare-handed before?"}, {"value": "Supervisor never enforces", "label": "Supervisor never enforces", "probe": "What made that OK here? Have you/others done this task bare-handed before?"}, {"value": "Other", "label": "Other", "probe": "What made that OK here? Have you/others done this task bare-handed before?"}]'::jsonb, true, false, false, '{}'::jsonb, 30),
  ('H4', 'hand_ppe', array['INV']::text[], 3, 'Would the right glove have prevented or reduced this injury? (Be honest — cotton doesn’t stop wire.)', null, 'chips', '[{"value": "Yes", "label": "Yes"}, {"value": "Reduced", "label": "Reduced"}, {"value": "No", "label": "No"}, {"value": "Unknown", "label": "Unknown"}]'::jsonb, true, false, false, '{}'::jsonb, 40),
  ('H5', 'hand_ppe', array['INV']::text[], 3, 'Could a different tool, jig, guard, fixture, or method keep the hand out of the hazard altogether?', null, 'text', '[]'::jsonb, true, false, false, '{}'::jsonb, 50),
  ('H6', 'hand_ppe', array['SUP']::text[], 3, 'What are the written hand-protection expectations for this task? Are they enforced the same for everyone?', null, 'chips', '[{"value": "Written & enforced", "label": "Written & enforced"}, {"value": "Written, not enforced", "label": "Written, not enforced"}, {"value": "Unwritten custom", "label": "Unwritten custom"}, {"value": "None", "label": "None"}, {"value": "Conflict between policy and practice", "label": "Conflict between policy and practice"}]'::jsonb, true, false, false, '{}'::jsonb, 60),
  ('H7', 'hand_ppe', array['SUP']::text[], 3, 'Have supervisors seen people doing this task without required hand protection? What was done?', null, 'chips', '[{"value": "Never seen", "label": "Never seen"}, {"value": "Seen, said nothing", "label": "Seen, said nothing"}, {"value": "Seen, coached once", "label": "Seen, coached once"}, {"value": "Seen, progressive discipline", "label": "Seen, progressive discipline"}, {"value": "Don’t know", "label": "Don’t know"}]'::jsonb, false, true, false, '{}'::jsonb, 70),
  ('H8', 'hand_ppe', array['SUP']::text[], 3, 'Are the correct gloves stocked at the point of use, right sizes, replaced when worn? Who owns stocking?', null, 'chips', '[{"value": "Yes", "label": "Yes"}, {"value": "Sometimes", "label": "Sometimes"}, {"value": "No", "label": "No"}, {"value": "Unknown", "label": "Unknown"}]'::jsonb, true, false, false, '{}'::jsonb, 80),
  ('H9', 'hand_ppe', array['IP']::text[], 3, 'Was there anything about the task that made gloves impractical (dexterity, contamination, fit, wet, cold)?', null, 'text', '[]'::jsonb, false, true, false, '{}'::jsonb, 90),
  ('H10', 'hand_ppe', array['INV']::text[], 3, 'Latent: Is the tool/equipment designed so bare hands feel necessary (poor grip, no fixture, awkward access)? Can we redesign?', null, 'text', '[]'::jsonb, false, true, false, '{}'::jsonb, 100),
