  ('C1', 'chemical', array['SUP','INV']::text[], 3, 'Exact product, concentration, SDS on file? Attach SDS.', 'Expected answer: product + SDS upload', 'text', '[]'::jsonb, true, false, false, '{}'::jsonb, 10),
