  ('C8', 'chemical', array['IP','SUP']::text[], 3, 'Exposure response: eyewash/rinse used? Poison Control / medical contacted? Time to treatment? PPE during response?', 'Critical if exposure. If that does not apply, mark N/A with a one-line reason.', 'checklist', '[]'::jsonb, true, false, false, '{}'::jsonb, 80),
  ('C9', 'chemical', array['SUP']::text[], 3, 'Secondary containment, spill kit, and PPE staged before transfer?', null, 'chips', '[{"value": "Yes", "label": "Yes"}, {"value": "Partial", "label": "Partial"}, {"value": "No", "label": "No"}]'::jsonb, true, false, false, '{}'::jsonb, 90),
