  ('V1', 'vehicle', array['IP','SUP']::text[], 3, 'Was a pre-trip / circle check done? Did it catch the condition that mattered?', null, 'chips', '[{"value": "Done & caught", "label": "Done & caught"}, {"value": "Done, missed it", "label": "Done, missed it"}, {"value": "Not done", "label": "Not done", "probe": "What made that possible? Has it happened before? What would have caught it?"}, {"value": "Not required for this unit", "label": "Not required for this unit"}]'::jsonb, true, false, false, '{}'::jsonb, 10),
  ('V2', 'vehicle', array['IP']::text[], 3, 'Speed, road, visibility, weather, ice/gravel vs. limits and journey plan?', null, 'chips', '[{"value": "Within limits", "label": "Within limits"}, {"value": "Over", "label": "Over"}, {"value": "Conditions changed", "label": "Conditions changed"}, {"value": "No journey plan", "label": "No journey plan"}]'::jsonb, true, false, false, '{}'::jsonb, 20),
